-- Reporting read model. Rebuilt from events; safe to truncate and replay from the archive queue.
IF OBJECT_ID('dbo.ProcessedMessage') IS NULL
CREATE TABLE dbo.ProcessedMessage (MessageId UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, Consumer NVARCHAR(100) NOT NULL, ProcessedUtc DATETIME2 NOT NULL);
IF OBJECT_ID('dbo.DimProduct') IS NULL
CREATE TABLE dbo.DimProduct (Sku NVARCHAR(40) NOT NULL PRIMARY KEY, StyleCode NVARCHAR(20) NOT NULL, Name NVARCHAR(200) NOT NULL, Brand NVARCHAR(20) NULL, CategoryCode NVARCHAR(20) NOT NULL, Season NVARCHAR(10) NULL, Colour NVARCHAR(40) NULL, Size NVARCHAR(10) NULL, UpdatedUtc DATETIME2 NOT NULL);
IF OBJECT_ID('dbo.DimStore') IS NULL
CREATE TABLE dbo.DimStore (StoreCode NVARCHAR(10) NOT NULL PRIMARY KEY, Name NVARCHAR(100) NOT NULL, LocationType NVARCHAR(10) NOT NULL, Country NCHAR(2) NOT NULL, City NVARCHAR(60) NULL, Currency NCHAR(3) NOT NULL, OpenedOn DATE NOT NULL, ClosedOn DATE NULL);
IF OBJECT_ID('dbo.FactSales') IS NULL
CREATE TABLE dbo.FactSales (Id BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY, Channel NVARCHAR(10) NOT NULL, LocationCode NVARCHAR(10) NOT NULL, Market NCHAR(2) NOT NULL, BusinessDate DATE NOT NULL, SourceRef NVARCHAR(40) NOT NULL, Sku NVARCHAR(40) NOT NULL, Quantity INT NOT NULL, NetAmount DECIMAL(18,2) NOT NULL, NetAmountEur DECIMAL(18,2) NOT NULL, Currency NCHAR(3) NOT NULL, PromotionCode NVARCHAR(30) NULL, Loyalty BIT NOT NULL);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_FactSales_Date')
CREATE INDEX IX_FactSales_Date ON dbo.FactSales (BusinessDate, Channel, LocationCode) INCLUDE (Sku, Quantity, NetAmountEur);
IF OBJECT_ID('dbo.FactWebOrder') IS NULL
CREATE TABLE dbo.FactWebOrder (OrderId UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, OrderNo NVARCHAR(30) NOT NULL, Channel NVARCHAR(10) NOT NULL, Market NCHAR(2) NOT NULL, DeliveryMethod NVARCHAR(20) NULL, CollectStoreCode NVARCHAR(10) NULL, Total DECIMAL(18,2) NOT NULL, TotalEur DECIMAL(18,2) NOT NULL, Currency NCHAR(3) NOT NULL, Lines INT NOT NULL, Status NVARCHAR(20) NOT NULL, CancelReason NVARCHAR(200) NULL, SubmittedUtc DATETIME2 NOT NULL, CompletedUtc DATETIME2 NULL, CancelledUtc DATETIME2 NULL);
IF OBJECT_ID('dbo.FactReturn') IS NULL
CREATE TABLE dbo.FactReturn (Id BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY, RmaNo NVARCHAR(30) NOT NULL, OrderNo NVARCHAR(30) NULL, StoreCode NVARCHAR(10) NULL, Sku NVARCHAR(40) NOT NULL, Quantity INT NOT NULL, Grade NVARCHAR(2) NULL, RefundAmount DECIMAL(18,2) NOT NULL, RefundAmountEur DECIMAL(18,2) NOT NULL, Currency NCHAR(3) NOT NULL, RefundMethod NVARCHAR(20) NULL, BusinessDate DATE NOT NULL);
IF OBJECT_ID('dbo.FactStockAlert') IS NULL
CREATE TABLE dbo.FactStockAlert (Id BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY, LocationCode NVARCHAR(10) NOT NULL, Sku NVARCHAR(40) NOT NULL, OnHand INT NOT NULL, RaisedUtc DATETIME2 NOT NULL);
IF OBJECT_ID('dbo.ReportRun') IS NULL
CREATE TABLE dbo.ReportRun (Id BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY, ReportName NVARCHAR(50) NOT NULL, BusinessDate DATE NOT NULL, FileName NVARCHAR(200) NOT NULL, Rows INT NOT NULL, RequestedBy NVARCHAR(100) NULL, CreatedUtc DATETIME2 NOT NULL);
